import os
import torch


class Config:
    """
    Configuration parameters for the RNA Degradation Prediction pipeline.
    Implements the settings for the 'Synchronized-Augmented Wide-Stream Residual BiGRU' strategy.
    """

    # =========================================================================
    # Directories and File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_27"

    # Input Data Files (Parquet format as generated by metadata script)
    TRAIN_FILE = os.path.join(METADATA_DIR, "train.parquet")
    VAL_FILE = os.path.join(METADATA_DIR, "val.parquet")
    TEST_FILE = os.path.join(METADATA_DIR, "test.parquet")

    # Submission Files
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")
    SUBMISSION_FILE = os.path.join(WORKING_DIR, "submission.csv")

    # Model Checkpoint
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LEN = 107
    PRED_LEN = 68

    # Targets to be predicted and scored
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = len(TARGET_COLS)

    # Targets available in training but ignored to reduce noise
    IGNORE_COLS = ["deg_pH10", "deg_50C"]

    # Vocabularies
    # Atomic Sequence Tokens
    NUC_VOCAB = ["A", "G", "C", "U"]
    NUC_TO_ID = {c: i for i, c in enumerate(NUC_VOCAB)}

    # Predicted Loop Types
    # S: Stem, M: Multiloop, I: Internal, B: Bulge, H: Hairpin, E: Dangling End, X: External
    LOOP_VOCAB = ["S", "M", "I", "B", "H", "E", "X"]
    LOOP_TO_ID = {c: i for i, c in enumerate(LOOP_VOCAB)}

    # Augmentation Constants
    # When dropping a base pair, we set the loop type to 'X' (External/Unpaired)
    AUG_LOOP_TOKEN = "X"
    AUG_LOOP_ID = LOOP_TO_ID[AUG_LOOP_TOKEN]

    # =========================================================================
    # Model Architecture Hyperparameters
    # =========================================================================
    # Wide-Stream Residual BiGRU
    EMBED_DIM = 128  # High-dimensional embeddings for inputs
    HIDDEN_DIM = 512  # Residual stream width (BiGRU hidden size = 256 * 2)
    N_LAYERS = 6  # Number of residual blocks
    DROPOUT = 0.1  # Standard dropout

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    EPOCHS = 20
    BATCH_SIZE = 64  # A100 can handle larger batches for this sequence length
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 0.01  # High weight decay to constrain the wide backbone
    MAX_GRAD_NORM = 1.0

    # Computing
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # =========================================================================
    # Setup Methods
    # =========================================================================
    def __init__(self, debug=False, subset_size=None):
        """
        Initialize configuration.

        Args:
            debug (bool): If True, enables debug mode (not strictly used here but good for API).
            subset_size (int, optional): If provided, limits dataset size for debugging.
        """
        self.debug = debug
        self.subset_size = subset_size

        # Ensure working directory exists
        os.makedirs(self.WORKING_DIR, exist_ok=True)

    def __str__(self):
        """String representation of the config for logging."""
        return (
            f"Config(hidden_dim={self.HIDDEN_DIM}, layers={self.N_LAYERS}, "
            f"lr={self.LEARNING_RATE}, device={self.DEVICE})"
        )
